          content: "핀페시아는 인도 제약사 Cipla에서 제조하는 피나스테리드(Finasteride) 1mg 정제예요. 국내 정식 허가 제품이 아니라 해외 직구로 구매하는 분이 많아요. 주성분 자체는 프로페시아(한국오가논)와 동일한 피나스테리드 1mg이지만, 한국 식약처 품질 관리 체계 밖에 있다는 점이 다른 제네릭과 가장 큰 차이예요.\n\n피나스테리드는 5α-환원효소 2형을 선택적으로 차단해요. 남성호르몬 테스토스테론이 DHT(디하이드로테스토스테론)로 전환되는 걸 막아서, 혈중 DHT를 65~70% 줄여줘요. DHT가 모낭을 위축시키는 주범이기 때문에 이 과정을 막으면 탈모 진행이 억제되고 발모도 촉진돼요.\n\n인도 CDSCO(의약품표준관리기구) 기준으로 제조되기 때문에 국내 제네릭(피나원, 헤어그로 등)과 품질 검증 체계가 달라요. 부작용 발생 시 국내 약화사고 피해 구제 대상에서 제외될 수 있어요. 가격이 저렴하다는 장점이 있지만, 장기 복용 약이라 안전성 측면에서 국내 허가 제품을 선택하는 게 더 안전해요.\n\n코팅 정제 형태이고, 임산부가 분쇄된 정제에 피부가 닿으면 남성 태아 생식기 발달 이상 위험이 있어요. 통째로 삼키고, 쪼개거나 가루로 만들지 마세요.",
