      "h1": "미노페시아 가격, 28정·84정 단가와 프로페시아 1년 비용 비교",
      "metaDescription": "미노페시아정 1mg 28정은 인증약국 5곳 기준 13,200원에서 21,700원 사이에 거래된다. 84정 가격과 1정당 단가, 오리지널 프로페시아와의 1년 비용 차이, 복용법과 부작용을 정리한 안내다.",
