      "heroDescription": "미노페시아정 1mg 28정은 인증약국 5곳 기준 13,200원부터 21,700원까지 거래돼요. 84정은 46,200원에서 49,560원 사이고요. 1정당 단가로 보면 28정 최저가가 84정보다 오히려 낮아서, 무조건 큰 포장이 유리하진 않아요. 오리지널 프로페시아와 1년 비용을 비교하면 격차가 크게 벌어져요.",
