            "카필러스폼은 동아제약(주)에서 만드는 미녹시딜(Minoxidil) 5% 폼 타입 외용제예요. 같은 동아제약의 카필러스캡슐(먹는 탈모 보조 치료제)과 이름이 비슷하지만, 카필러스폼은 두피에 바르는 완전히 다른 제품이에요. 캡슐은 약용효모·시스틴 복합 영양제이고, 폼은 미녹시딜 혈관 확장제예요.\n\n미녹시딜은 칼륨 채널을 열어서 두피 혈관을 확장시키고 모낭 주변 혈류를 늘려줘요. 위축된 모낭에 산소와 영양이 더 많이 공급되면서 휴지기 모낭이 다시 성장기로 전환돼요. 폼 타입은 액상 미녹시딜에 비해 프로필렌글리콜(PG)이 적거나 없어서 두피 자극이 덜한 게 장점이에요.\n\n폼은 도포 후 몇 분이면 건조돼서 액상보다 머리카락이 덜 젖어요. 출근 전이나 외출 전에 사용하기 편리하고, 헤어스타일이 덜 망가져요. 다만 스포이트로 정밀한 양을 계량하기 어렵고, 머리카락이 긴 분은 두피까지 도달시키기 어려울 수 있어요.\n\n에탄올이 포함되어 있어서 화기 근처에 두면 안 돼요. 에어로졸 용기라 고온(45도 이상)에 노출되면 폭발 위험이 있으니 차량 안이나 직사광선을 피해서 보관하세요.",
